import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, texture } from 'three/tsl';

function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();
  const timelines = [];
  const resources = [];

  const ink = 0x16161d;
  const paper = 0xe8ecf2;
  const accent = 0xff2a38;
  const surface = 0x0b0b10;

  const gradientT = smoothstep(0.0, 1.0, uv().y);
  const gradientNode = mix(
    vec3(
      ((surface >> 16) & 255) / 255,
      ((surface >> 8) & 255) / 255,
      (surface & 255) / 255
    ),
    vec3(
      ((ink >> 16) & 255) / 255,
      ((ink >> 8) & 255) / 255,
      (ink & 255) / 255
    ),
    gradientT
  );

  const panelGeometry = new PlaneGeometry(2.15, 1.28, 1, 1);
  const panelMaterial = new MeshBasicNodeMaterial();
  panelMaterial.colorNode = gradientNode;
  panelMaterial.toneMapped = false;

  const panel = new Mesh(panelGeometry, panelMaterial);
  panel.position.z = 0;
  root.add(panel);
  resources.push(panelGeometry, panelMaterial);

  const accentGeometry = new PlaneGeometry(0.08, 0.82, 1, 1);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: accent,
    toneMapped: false
  });
  const accentBar = new Mesh(accentGeometry, accentMaterial);
  accentBar.position.set(-0.82, 0, 0.025);
  root.add(accentBar);
  resources.push(accentGeometry, accentMaterial);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (typeof item?.text !== 'string') continue;

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: '#e8ecf2',
      align: 'left'
    });

    textObject.position.set(-0.67, -0.02, 0.04);
    root.add(textObject);
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl)
      .then((loadedTexture) => {
        if (!loadedTexture || root.userData.cleaned) return;
        loadedTexture.colorSpace = ctx.THREE.SRGBColorSpace;
        panelMaterial.colorNode = mix(
          gradientNode,
          texture(loadedTexture).rgb,
          0.22
        );
        panelMaterial.needsUpdate = true;
        resources.push(loadedTexture);
      })
      .catch(() => {});
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (root.userData.cleaned) return;
    root.userData.cleaned = true;

    for (const timeline of timelines) {
      if (timeline?.kill) timeline.kill();
    }

    root.traverse((object) => {
      if (object.geometry?.dispose) object.geometry.dispose();
      if (object.material) {
        const materials = Array.isArray(object.material)
          ? object.material
          : [object.material];

        for (const material of materials) {
          if (material.dispose) material.dispose();
        }
      }
    });

    for (const resource of resources) {
      if (resource?.dispose && resource !== panelGeometry && resource !== accentGeometry) {
        resource.dispose();
      }
    }
  };

  return root;
}

export default createNode;
